pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const dropZone=document.getElementById("drop-zone"),fileInput=document.getElementById("file-input"),loading=document.getElementById("loading"),results=document.getElementById("results"),checkList=document.getElementById("check-list"),statusBadge=document.getElementById("status-badge");async function processFile(t){if(t){dropZone.style.display="none",loading.style.display="block";try{const e=await t.arrayBuffer(),s=await pdfjsLib.getDocument(e).promise;let a="",n=!1;for(let t=1;t<=s.numPages;t++){const e=await s.getPage(t),i=(await e.getTextContent()).items;let l={};i.forEach(t=>{const e=Math.round(t.transform[5]);l[e]||(l[e]=0),l[e]++,a+=t.str+" "});Object.values(l).filter(t=>t>3).length>5&&(n=!0)}runAtsCheck(a,n,t.size)}catch(t){alert("Error processing PDF."),location.reload()}}}function runAtsCheck(t,e,s){loading.style.display="none",results.style.display="block",checkList.style.display="block";const a=[{title:"Text Searchability",status:t.trim().length>100?"pass":"fail",passMsg:"Your PDF is text-based and searchable.",failMsg:"Your PDF seems to be an image. ATS cannot read this."},{title:"Layout Simplicity",status:e?"warn":"pass",passMsg:"Single-column layout or simple structure detected.",failMsg:"Complex multi-column layout detected. Some older ATS might struggle."},{title:"File Size Optimization",status:s<5e5?"pass":"warn",passMsg:"Optimal file size for quick uploading.",failMsg:"File is a bit large. Consider compressing for faster parsing."},{title:"Standard Section Headings",status:/Experience|Education|Skills/i.test(t)?"pass":"warn",passMsg:"Standard ATS-friendly headings found.",failMsg:"Standard headings not detected. Use words like 'Experience' or 'Education'."}];let n=a.filter(t=>"pass"===t.status).length;4===n?(statusBadge.textContent="ATS READY",statusBadge.className="status-badge status-ats-ready"):n>=2?(statusBadge.textContent="OPTIMIZATION RECOMMENDED",statusBadge.className="status-badge status-ats-warning"):(statusBadge.textContent="ATS COMPATIBILITY LOW",statusBadge.className="status-badge status-ats-danger"),checkList.innerHTML=a.map(t=>`\n                <div class="check-item">\n                    <div class="check-icon">${"pass"===t.status?"✅":"warn"===t.status?"⚠️":"❌"}</div>\n                    <div class="check-content">\n                        <h4>${t.title}</h4>\n                        <p>${"pass"===t.status?t.passMsg:(t.status,t.failMsg)}</p>\n                    </div>\n                </div>\n            `).join(""),setTimeout(()=>{const t=a.map(t=>`${t.title}: ${t.status.toUpperCase()}`).join("\n"),e=new Blob([t],{type:"text/plain"}),s=URL.createObjectURL(e),n=document.createElement("a");n.href=s,n.download="resume_optimization_report.txt",n.click()},1500)}dropZone.onclick=()=>fileInput.click(),fileInput.onchange=t=>processFile(t.target.files[0]);